            float2 norm = normalize(float2(dx,dy));

            float4 blurTexColor = amzTexture(1,amzScreenNorm() + norm*length(offs)*(amzp_disort*0.055));

            float turbBase = turbulence((st-0.5)/amzp_maskScale+0.5, 3, float2(0.), amzp_maskEvolution + 91.935*amzp_maskSeed);
            float TINT_RANGE = 0.02;
            float turb = smoothstep( amzp_maskStrength - (TINT_RANGE+.2), amzp_maskStrength-(TINT_RANGE+.1), turbBase);
            float suppress = smoothstep( amzp_maskStrength - (TINT_RANGE+.1), amzp_maskStrength-TINT_RANGE, turbBase);
            float ttint = smoothstep( amzp_maskStrength - TINT_RANGE, amzp_maskStrength-0.001, turbBase);

            float p = blurTexColor.a;


            float dist = 1. - (amzp_distance * 0.4 + 0.5);
            float pp = pow((1.-abs(p-dist)),(1.-(amzp_thickness*0.9*suppress))*30.);
            pp *= smoothstep(0.01,0.12,p);
            pp *= smoothstep(1.0,0.999,p);

            float qq = pow((1.-abs(p-dist)),(1.-(amzp_thickness*0.9*suppress))*25.);
            qq *= smoothstep(0.01,0.12,p);
            qq *= smoothstep(1.0,0.999,p);

            if((amzp_renderContours>0.5)) {
                float arad = amzp_contourAngle * 0.0174533;
                float2 st2 = st;
                st2.y += blurTexColorMid.a*0.1;
                st2 *= rot2d(length(offs*amzp_disort*1.1)*0.2+arad);
                st2.y += blurTexColorMid.a*0.1;
                float lines = saturate(sin((st2.y+amzp_contourOffset+(offs.y*amzp_disort*0.015)) * amzp_contourCount)) * smoothstep(0.1,0.2,blurTexColorMid.a);

                pp += pow(lines,(1.-(amzp_thickness*0.9*suppress))*30.);
                qq += pow(lines,(1.-(amzp_thickness*0.9*suppress))*25.);
            }

            float4 c0 = float4(pow( float3(pp), 1./amzp_color1.rgb),pp) * amzp_alpha;
            float4 c1 = float4(pow( float3(qq), 1./amzp_color2.rgb),qq) * amzp_glowAlpha;
            float4 c = saturate(c0 + c1);

            c *= (mix(amzp_maskColor,float4(1.),ttint)*turb);

            amzOutput = texColor * amzp_fill * (1.-c.a) + c;

        }


half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }
